sparql_tries.sparql:
SELECT DISTINCT ?modelYear
WHERE {
  ?campaign rc:campaignNumber "26V430000" ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model ;
           rc:modelYear ?modelYear .
  ?model rc:name "TELLURIDE" ;
         rc:ofMake ?make .
  ?make rc:name "KIA" .
}
ORDER BY ?modelYear

SELECT DISTINCT ?category WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber "10V388000" ;
            rc:affectsComponent ?comp .
  ?comp skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?parent }
  ?top rc:name ?category .
}
ORDER BY ?category

SELECT ?reportDate WHERE {
  ?campaign rc:campaignNumber "23V651000" ;
            rc:reportReceivedDate ?reportDate .
}

SELECT ?potentiallyAffected WHERE {
  ?campaign rc:campaignNumber "26V430000" ;
            rc:potentiallyAffected ?potentiallyAffected .
}

SELECT DISTINCT ?campaign ?make WHERE {
  ?c a rc:RecallCampaign ;
     rc:doNotDrive true ;
     rc:campaignNumber ?campaign ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?make .
  FILTER(?make IN ("HYUNDAI", "KIA", "GENESIS"))
}
ORDER BY ?make ?campaign

SELECT ?campaignNumber WHERE {
  ?c a rc:RecallCampaign ;
     rc:initiatedBy ?ib ;
     rc:campaignNumber ?campaignNumber .
  FILTER(REGEX(STR(?ib), "OVSC|Vehicle Safety Compliance", "i"))
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campaignNumber ?receivedDate
WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:campaignNumber ?campaignNumber ;
            rc:reportReceivedDate ?receivedDate ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:name "PALISADE" ;
         rc:ofMake ?make .
  ?make rc:name "HYUNDAI" .
  FILTER(YEAR(?receivedDate) = 2024)
}
ORDER BY ?receivedDate ?campaignNumber

SELECT DISTINCT ?modelName ?makeName WHERE {
  ?camp a rc:RecallCampaign ;
        rc:affectsComponent ?comp ;
        rc:affects ?variant .
  ?comp rc:name "SERVICE BRAKES, HYDRAULIC:ANTILOCK/TRACTION CONTROL/ELECTRONIC LIMITED SLIP:CONTROL UNIT/MODULE" .
  ?variant rc:ofModel ?model .
  ?model rc:name ?modelName ;
         rc:ofMake ?make .
  ?make rc:name ?makeName .
}
ORDER BY ?makeName ?modelName

SELECT ?compName (COUNT(DISTINCT ?c) AS ?campaignCount) WHERE {
  ?c rc:affectsComponent ?comp ;
     rc:affects ?v .
  ?v rc:ofModel/rc:ofMake/rc:name ?mk .
  FILTER(?mk IN ("HYUNDAI", "KIA"))
  ?comp rc:name ?compName .
  FILTER NOT EXISTS { ?child skos:broader ?comp }
  FILTER EXISTS { ?h1 rc:affectsComponent ?comp ; rc:affects/rc:ofModel/rc:ofMake/rc:name "HYUNDAI" . }
  FILTER EXISTS { ?k1 rc:affectsComponent ?comp ; rc:affects/rc:ofModel/rc:ofMake/rc:name "KIA" . }
}
GROUP BY ?compName
ORDER BY DESC(?campaignCount)
LIMIT 10

SELECT ?campNo (COUNT(DISTINCT ?makeName) AS ?brandCount) (GROUP_CONCAT(DISTINCT ?makeName; separator=", ") AS ?brands)
WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campNo ;
     rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:ofMake ?make .
  ?make rc:name ?makeName .
  FILTER(?makeName IN ("HYUNDAI", "KIA", "GENESIS"))
}
GROUP BY ?campNo
HAVING (COUNT(DISTINCT ?makeName) > 1)
ORDER BY DESC(?brandCount) ?campNo

SELECT DISTINCT ?campaignNumber WHERE {
  ?camp a rc:RecallCampaign ;
        rc:campaignNumber ?campaignNumber ;
        rc:affects ?v .
  ?v rc:modelYear ?y ;
     rc:ofModel ?m .
  ?m rc:name "SANTA FE" ;
     rc:ofMake ?mk .
  ?mk rc:name "HYUNDAI" .
  FILTER(STR(?y) = "2021")
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?modelName ?compName
WHERE {
  # Component recalled on the KIA TELLURIDE
  ?tRc a rc:RecallCampaign ;
       rc:affects ?tVariant ;
       rc:affectsComponent ?comp .
  ?tVariant rc:ofModel ?tModel .
  ?tModel rc:name "TELLURIDE" ;
          rc:ofMake ?tMake .
  ?tMake rc:name "KIA" .

  # Same component recalled on a GENESIS model
  ?gRc a rc:RecallCampaign ;
       rc:affects ?gVariant ;
       rc:affectsComponent ?comp .
  ?gVariant rc:ofModel ?gModel .
  ?gModel rc:ofMake ?gMake ;
          rc:name ?modelName .
  ?gMake rc:name "GENESIS" .

  ?comp rc:name ?compName .
}
ORDER BY ?modelName ?compName

SELECT ?modelName ?makeName (COUNT(DISTINCT ?campaign) AS ?campaignCount)
WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:name ?modelName ;
         rc:ofMake ?make .
  ?make rc:name ?makeName .
}
GROUP BY ?modelName ?makeName
ORDER BY DESC(?campaignCount)

SELECT (COUNT(DISTINCT ?c) AS ?campaignCount) WHERE {
  ?c a rc:RecallCampaign ;
     rc:reportReceivedDate ?d ;
     rc:affects ?v .
  ?v rc:ofModel ?m .
  ?m rc:ofMake ?mk .
  ?mk rc:name ?mkName .
  FILTER(UCASE(STR(?mkName)) IN ("HYUNDAI", "KIA", "GENESIS"))
  FILTER(YEAR(?d) = 2023)
}

SELECT ?topName (COUNT(DISTINCT ?model) AS ?modelCount) WHERE {
  ?camp rc:affectsComponent ?c .
  ?c skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?parent . }
  ?top rc:name ?topName .
  ?camp rc:affects ?variant .
  ?variant rc:ofModel ?model .
}
GROUP BY ?topName
ORDER BY DESC(?modelCount) ?topName

SELECT ?campaignNumber ?potentiallyAffected WHERE {
  ?c a rc:RecallCampaign ;
     rc:parkOutside true ;
     rc:campaignNumber ?campaignNumber ;
     rc:potentiallyAffected ?potentiallyAffected .
}
ORDER BY DESC(?potentiallyAffected)
LIMIT 1

SELECT (COUNT(DISTINCT ?campaign) AS ?odiCampaignCount) WHERE {
  ?campaign a rc:RecallCampaign ;
            rc:initiatedBy ?initiator .
  FILTER(
    CONTAINS(UCASE(STR(?initiator)), "ODI") ||
    CONTAINS(UCASE(STR(?initiator)), "OFFICE OF DEFECTS INVESTIGATION")
  )
}

SELECT ?topName (COUNT(DISTINCT ?c) AS ?campaigns) WHERE {
  ?make rc:name "GENESIS" .
  ?model rc:ofMake ?make .
  ?variant rc:ofModel ?model .
  ?c rc:affects ?variant ;
     rc:affectsComponent ?comp .
  ?comp skos:broader* ?top .
  FILTER NOT EXISTS { ?top skos:broader ?parent }
  ?top rc:name ?topName .
}
GROUP BY ?topName
ORDER BY DESC(?campaigns)
LIMIT 1

SELECT (COUNT(DISTINCT ?year) AS ?yearCount) WHERE {
  ?make rc:name "HYUNDAI" .
  ?model rc:ofMake ?make ;
         rc:name "SONATA" .
  ?variant rc:ofModel ?model ;
           rc:modelYear ?year .
  ?campaign rc:affects ?variant .
}

SELECT ?year (COUNT(DISTINCT ?camp) AS ?recallCount) WHERE {
  ?camp a rc:RecallCampaign ;
        rc:reportReceivedDate ?d ;
        rc:affects ?variant .
  ?variant rc:ofModel ?model .
  ?model rc:ofMake ?make .
  ?make rc:name ?makeName .
  FILTER(?makeName IN ("HYUNDAI", "KIA", "GENESIS"))
  BIND(YEAR(?d) AS ?year)
}
GROUP BY ?year
ORDER BY DESC(?recallCount)
LIMIT 1

SELECT DISTINCT ?campaignNumber WHERE {
  ?rc a rc:RecallCampaign ;
      rc:campaignNumber ?campaignNumber .
  OPTIONAL { ?rc rc:affectsComponent ?comp . ?comp rc:name ?compName . }
  OPTIONAL { ?rc rc:defectSummary ?defect . }
  FILTER (
    (BOUND(?compName) && REGEX(?compName, "HYDROGEN", "i")) ||
    (BOUND(?defect) && REGEX(?defect, "hydrogen", "i") && REGEX(?defect, "leak|detect|sensor", "i"))
  )
}
ORDER BY ?campaignNumber

SELECT DISTINCT ?campNo WHERE {
  ?camp a rc:RecallCampaign ;
        rc:campaignNumber ?campNo ;
        rc:affectsComponent ?comp .
  ?comp rc:name ?cname .
  FILTER(CONTAINS(UCASE(STR(?cname)), "CHARGING"))
}
ORDER BY ?campNo

SELECT DISTINCT ?campaignNo ?defectSummary WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNo .
  OPTIONAL { ?c rc:defectSummary ?defectSummary }
  OPTIONAL { ?c rc:rootCause ?rootCause }
  OPTIONAL {
    ?c rc:affectsComponent ?comp .
    ?comp rc:name ?compName .
  }
  FILTER (
    (regex(str(?defectSummary), "water|moisture|humid|wet|corrosion", "i") ||
     regex(str(?rootCause), "water|moisture|humid|wet|corrosion", "i"))
    &&
    (regex(str(?defectSummary), "tow|trailer|hitch", "i") ||
     regex(str(?rootCause), "tow|trailer|hitch", "i") ||
     regex(str(?compName), "tow|trailer|hitch", "i"))
  )
}
ORDER BY ?campaignNo

SELECT DISTINCT ?campaignNumber WHERE {
  ?c a rc:RecallCampaign ;
     rc:campaignNumber ?campaignNumber ;
     rc:defectSummary ?d .
  FILTER(REGEX(?d, "connecting.rod", "i") && REGEX(?d, "bearing", "i") && REGEX(?d, "wear", "i"))
}
ORDER BY ?campaignNumber
